@startuml

class Animal {
  + ID
  + Name
}

class Breed {
  + Name
}

class Person {
  + ID
  + Name
  + Address
  + Phone
}

class Owner extends Person {}

class Physician extends Person {}

class Appointment {
  + Date
  + Time
}

class MedicalCondition {
  + Common_Name
  + Scientific_Name
}

class AppointmentCondition {
}

Animal "*" -- "0..1" Owner : owned by
Animal "*" -- "0..1" Breed : breed
Appointment "*" -- "1" Physician : responsible physician
Appointment "*" -- "1" Animal : attended by
Appointment "*" -- "1" Owner : attended by
Appointment "*" -- "*" MedicalCondition : detects
AppointmentCondition "*" -- "1" Appointment
AppointmentCondition "*" -- "1" MedicalCondition
Breed "*" -- "*" MedicalCondition : common conditions

@enduml

